                var upper = AdvSimd.ShiftLeftAndInsert(r0 >>> 8, r1, 8);
                var start = r1 & mask;
                into.Store(stride, 0, 0, Neon.Convert24(AdvSimd.Arm64.ZipLow(lower, upper)));
                into.Store(stride, 0, 4, Neon.Convert24(AdvSimd.Arm64.ZipHigh(lower, upper)));
